import{_ as a,o as i,c as t,a3 as n}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"ATLAS Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/atlas-plugins/index.md","filePath":"en/projects/atlas-plugins/index.md","lastUpdated":1792857501000}'),r={name:"en/projects/atlas-plugins/index.md"};function o(s,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="atlas-plugins" tabindex="-1">ATLAS Plugins <a class="header-anchor" href="#atlas-plugins" aria-label="Permalink to &quot;ATLAS Plugins&quot;">​</a></h1><h2 id="back-up-and-restore-a-plugin-version" tabindex="-1">Back up and restore a plugin version <a class="header-anchor" href="#back-up-and-restore-a-plugin-version" aria-label="Permalink to &quot;Back up and restore a plugin version&quot;">​</a></h2><p>Since ATLAS 0.1.304:</p><ol><li>Back up HA/ATLAS and the plugin&#39;s own data first.</li><li>Import an existing plugin package in Plugin Manager and review the old/new versions and capabilities.</li><li>Back up and apply retains a server recovery snapshot before replacement. Review unknown compatibility explicitly; incompatible packages remain blocked.</li><li>To return, choose Restore on the plugin, review the saved version and apply. The currently installed version is backed up too.</li></ol><p>Browser data and data formats are not reset. An older plugin must support the existing data format. See <a href="./developers/compatibility#preserve-and-recover-data">limits and backup location</a>. The UI is verified in isolation and on Pi 5 and Proxmox with Icon Library, File Studio and Terminal; other plugins and data migrations require separate qualification.</p><p>This section collects everything that describes installable extensions rather than the ATLAS core itself: plugin contracts, repository format, publishing, update behavior and individual plugin pages.</p><div class="warning custom-block"><p class="custom-block-title">Development status</p><p>The plugin interfaces are still in progress. These pages document the current ATLAS state and will be expanded as the contracts become more stable.</p></div><h2 id="start-here" tabindex="-1">Start Here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start Here&quot;">​</a></h2><ul><li><a href="./repository-format">Repository Format</a>: <code>repository.json</code> structure, required fields, ATLAS marker and example.</li><li><a href="./plugin-template">Plugin Template</a>: use the template, customize a plugin, build its package and publish it.</li><li><a href="./developers/">Plugin Development</a>: plugin structure, manifests, Runtime lifecycle and publishing.</li><li><a href="./verified-plugins">Verified Plugins</a>: compact lists of verified and new unreviewed ATLAS plugins.</li><li><a href="./homeassistant-card-editor">Home Assistant Card Editor</a>: the first official ATLAS reference plugin.</li><li><a href="./file-studio">ATLAS File Studio</a>: second independent ATLAS plugin for approved Home Assistant file paths.</li><li><a href="./icon-studio">ATLAS Icon Studio</a>: manage, import and save icon sets for Home Assistant.</li><li><a href="./icon-library">ATLAS Icon Library</a>: browse icon sets and copy full icon names.</li><li><a href="./terminal">ATLAS Terminal</a>: authenticated browser terminal with optional SSH, Oh My Posh themes and a server-served Nerd Font.</li><li><a href="./automation-extractor">ATLAS Automation Exporter / Editor</a>: new plugin for analyzing, safely backing up and exporting Home Assistant automations.</li><li><a href="./demo-repository">Demo Repository</a>: public test repository for Administration, Hub and install flow.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>ATLAS plugins should extend the platform without directly changing core packages. This includes Home Assistant-oriented tools, card editors, diagnostics surfaces, renderers, themes, providers and later community extensions.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>A plugin should be installable, inspectable, activatable, updatable and removable in a traceable way:</p><ol><li>Read the manifest.</li><li>Check dependencies.</li><li>Register the plugin.</li><li>Provide services, commands or UI surfaces.</li><li>Activate the plugin.</li><li>Report diagnostics and status data.</li><li>Deactivate or remove it cleanly.</li></ol><h2 id="current-technical-anchor" tabindex="-1">Current Technical Anchor <a class="header-anchor" href="#current-technical-anchor" aria-label="Permalink to &quot;Current Technical Anchor&quot;">​</a></h2><p>The current entry point is the Runtime adapter. A <code>RuntimePlugin</code> can be translated into an ATLAS Runtime module with <code>createRuntimeModuleFromPlugin()</code>. <code>RuntimePluginCatalog</code> provides discovery, while Administration makes plugins visible, compares versions and prepares local installs.</p><p>The Plugin Hub now follows a clear start rule: if no plugins are installed, it points to Administration. With exactly one active plugin, ATLAS opens that plugin directly. With two or more active plugins, ATLAS shows the selection page. Planned or disabled plugins may be visible, but they are not started automatically.</p><p>The Plugin Hub can also prepare Home Assistant sidebar entries. The dialog lists current plugins dynamically, shows name, URL, version, status and icon suggestion, and copies either the URL alone or a ready-to-use <code>panel_iframe</code> block for <code>configuration.yaml</code>. The URL copy action is intended for Home Assistant dashboards of type <code>Webpage</code>. Long capability lists and sidebar URLs stay collapsed by default on plugin cards so the Hub remains compact with many plugins.</p><p>In Add-on mode, Card Editor, Administration and local plugin assets are served through ATLAS app routes. This preserves Home Assistant Ingress base paths in Hub and sidebar URLs, and other network clients do not need direct access to the separate development ports.</p><h3 id="shared-language-preference" tabindex="-1">Shared language preference <a class="header-anchor" href="#shared-language-preference" aria-label="Permalink to &quot;Shared language preference&quot;">​</a></h3><p>Administration and Plugin Hub support German, English and French. A language selected in either surface is saved and used by the other, including when the surfaces run on separate ports. An explicit <code>language</code> parameter in a plugin URL overrides that preference for the current visit.</p><p>For ATLAS File Studio, the Hub uses the plugin URL under <code>/plugin-assets/file-studio/index.html</code> on the ATLAS app port or through the matching Home Assistant Ingress/Webpage address. This URL is prepared even when older saved plugin state does not yet include a launch URL.</p><p>New local plugins also receive an automatic launch URL when their plugin folder contains an <code>index.html</code> and the manifest does not define <code>entry</code>. ATLAS then exposes <code>/plugin-assets/&lt;plugin-folder&gt;/index.html</code>, so users can choose between the Hub and a Home Assistant sidebar entry from the start.</p><h2 id="publishing-rules" tabindex="-1">Publishing Rules <a class="header-anchor" href="#publishing-rules" aria-label="Permalink to &quot;Publishing Rules&quot;">​</a></h2><p>Publishable plugins need clear names, explicit versions, documented dependencies, safe demo or fallback data, traceable build artifacts and notes for ATLAS, Home Assistant or HACS-oriented usage.</p><h2 id="automation-exporter-editor" tabindex="-1">Automation Exporter / Editor <a class="header-anchor" href="#automation-exporter-editor" aria-label="Permalink to &quot;Automation Exporter / Editor&quot;">​</a></h2><p>ATLAS Automation Exporter / Editor adds tools for detecting automations, showing their dependencies, creating a safety backup while reading and exporting an <code>id</code>-preserving archive version together with a cleaned import version without <code>id</code> for the Home Assistant YAML editor.</p>',27)])])}const g=a(r,[["render",o]]);export{h as __pageData,g as default};
